const resources = Object.fromEntries(
  Object.entries(baseResources).map(([locale, resource]) => [locale, {
    translation: { ...resource.translation, ...additionalTranslations[locale as keyof typeof additionalTranslations], ...statusTranslations[locale as keyof typeof statusTranslations] },
  }]),
);

export const supportedLocales = ["en", "fa", "ar", "de", "es", "fr", "ru", "tr", "hi", "zh", "ja", "pt"] as const;
const rtl = new Set(["fa", "ar", "ur", "he", "ps", "sd", "ug", "yi"]);

export function normalizeLocale(locale: string): string {
  const candidate = locale.trim().toLowerCase().split("-")[0];
  return supportedLocales.includes(candidate as typeof supportedLocales[number]) ? candidate : "en";
}

export function localeDirection(locale: string): "rtl" | "ltr" {
  return rtl.has(normalizeLocale(locale)) ? "rtl" : "ltr";
}

function readCachedLocale(): string {
  try {
    const raw = localStorage.getItem("pi-brain-preferences-v1");
    if (raw) {
      const parsed = JSON.parse(raw) as { language?: unknown };
      if (typeof parsed.language === "string") return normalizeLocale(parsed.language);
    }
  } catch { /* Local preferences are an optional startup cache. */ }
  return "en";
}

function applyDocumentLocale(locale: string): void {
  const copy = statusTranslations[locale as keyof typeof statusTranslations] ?? statusTranslations.en;
  document.title = copy.documentTitle;
  const description = document.querySelector<HTMLMetaElement>('meta[name="description"]');
  if (description) description.content = copy.documentDescription;
}

const initialLocale = readCachedLocale();
document.documentElement.lang = initialLocale;
document.documentElement.dir = localeDirection(initialLocale);
applyDocumentLocale(initialLocale);

i18n.use(initReactI18next).init({
  resources,
  lng: initialLocale,
  supportedLngs: [...supportedLocales],
  fallbackLng: false,
  defaultNS: "translation",
  load: "languageOnly",
  interpolation: { escapeValue: false },
  returnNull: false,
  returnEmptyString: false,
});

export async function applyLocale(locale: string): Promise<string> {
  const lang = normalizeLocale(locale);
  document.documentElement.lang = lang;
  document.documentElement.dir = localeDirection(lang);
  applyDocumentLocale(lang);
  await i18n.changeLanguage(lang);
  return lang;
}

export default i18n;
